bool isLucky(long long x) {
    if (x <= 0) return false;
    while (x) {
        int d = x % 10;
        if (d != 4 && d != 7) return false;
        x /= 10;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    if (!(cin >> n >> k)) return 0;

    const long long LIM = 20; // factorial grows huge; 20! > 1e18
    long long m = min(n, LIM);

    // Precompute factorials up to m
    vector<long long> fact(m + 1, 1);
    for (long long i = 1; i <= m; ++i) {
        long long v = fact[i - 1] * i;
        if (v > (long long)1e18) v = (long long)1e18;
        fact[i] = v;
    }

    if (k > fact[m]) {
        cout << -1;
        return 0;
    }

    // Count lucky indices among first n-m positions (fixed part)
    long long ans = 0;
    for (long long i = 1; i <= n - m; ++i) {
        if (isLucky(i) && isLucky(i)) {
            // ai = i in fixed part
            ans++;
        }
    }

    // Build last m elements: initial sequence [n-m+1, ..., n]
    vector<long long> elems;
    for (long long x = n - m + 1; x <= n; ++x) elems.push_back(x);

    // Convert k to 0-based
    k--;

    // Generate k-th permutation of elems in lexicographic order
    for (long long pos = 0; pos < m; ++pos) {
        long long block = fact[m - pos - 1];
        long long idx = k / block;
        k %= block;
        long long val = elems[(size_t)idx];
        elems.erase(elems.begin() + (size_t)idx);

        long long i = n - m + 1 + pos; // position in permutation
        if (isLucky(i) && isLucky(val)) ans++;
    }

    cout << ans;
    return 0;
}

